    nameInvalidWarn: "👤 *உங்கள் முழுப் பெயரைத் தட்டச்சு செய்யவும் (எ.கா. கார்த்திக் ராஜா):*\n\nஉங்கள் GST பில் PDF மற்றும் 1 வருட வாரண்டியில் இடம்பெறும்.",
    calculatingQuote: "✓ நன்றி, *{name}*! 🤝\n\n⚙️ *பின்கோடு {pin} க்கான அனைத்து பிராண்ட் விலையும் தயாராகிறது...*\nகேமரா, DVR/NVR, ஹார்ட் டிஸ்க், வயர் & 18% GST சேர்த்து உடனே அனுப்புகிறோம்!",
    allInclusiveTag: "அனைத்தும் அடக்கம்: கேமரா, DVR/NVR, ஹார்ட் டிஸ்க், வயர், ஃபிட்டிங் & 18% GST (மறைமுக கட்டணம் இல்லை!)",
