    setupDigitalIp: "டிஜிட்டல் IP (CAT6 PoE + NVR — அதிதெளிவு HD & ஸ்மார்ட் அலர்ட்)",
    mediaPhotoAck: "📸 *போட்டோ / ஆவணம் சேமிக்கப்பட்டது!*\n• வேறு கடை கொட்டேஷன் என்றால் 5%–10% குறைவான ஆஃபர் தருவோம்.\n• இடத்தின் போட்டோ என்றால் டெக்னீஷியன் சரிபார்ப்பார்.\n\n👇 *கீழே உங்கள் கொட்டேஷனை தொடரவும்:*",
    mediaVoiceAck: "🎙️ *வாய்ஸ் நோட் கிடைத்தது!*\nஎங்கள் குழு உங்கள் குரல் பதிவைக் கேட்கும்.\n\n👇 *உடனே விலை பார்க்க கீழே தேர்வு செய்யவும்:*",
    mediaVideoAck: "🎥 *வீடியோ சேமிக்கப்பட்டது!*\nஎங்கள் இன்ஜினியர் வீடியோவைப் பார்த்து கேபிள் & கேமரா இடத்தைத் திட்டமிடுவார்.\n\n👇 *தொடர கீழே தேர்வு செய்யவும்:*",
    mediaGenericAck: "👍 *கிடைத்தது!* 👇 *உங்கள் கொட்டேஷனை தொடருவோம்:*",
    intentWebStudio: "🌐 *3D CCTV வெப் ஸ்டுடியோ*\n\nகேமராக்களை ஒப்பிட்டு பிரவுசரில் விலை பார்க்க:\n👉 {url}\n\n_எப்போது வேண்டுமானாலும் WhatsApp-க்கு திரும்ப வரலாம்!_",
    intentCallback: "📞 *கால் புக் ஆனது!*\nஎங்கள் CCTV டெக்னீஷியன் விரைவில் போன் பண்ணுவார்.\n\n_அதற்குள் கீழே உள்ளதை முழுசா முடிங்க, கோட் ரெடியாகும்:_",
    intentPrice: "💰 *நேரடி மொத்த விலை + குறைந்த விலை உத்தரவாதம்:*\n• ₹1,409 + GST முதல் கேமராக்கள் (1 வருட இலவச ஹோம் வாரண்டி).\n• DVR/NVR, ஹார்ட் டிஸ்க், வயர் & ஃபிட்டிங் அனைத்தும் அடக்கம்.\n\n_சரியான மொத்த விலை பார்க்க கீழே தொடரவும்:_",
    intentWarranty: "🛡️ *1 வருட இலவச நேரடி வாரண்டி:*\n12 மாதத்தில் எந்தக் கோளாறும் ஏற்பட்டால் எங்கள் டெக்னீஷியன் ₹0 கட்டணத்தில் நேரில் வந்து சரிசெய்வார்.\n\n_தொடர கீழே தட்டவும்:_",
    intentLocation: "🚚 *உங்கள் இடத்திற்கே வந்து பொருத்தும் சேவை:*\nஅருகிலுள்ள மையத்திலிருந்து டெக்னீஷியன் முழு பொருட்களுடன் வருவார்.\n\n_பகுதியை உறுதி செய்ய கீழே தொடரவும்:_",
    intentReset: "🔄 *புதிதாகத் தொடங்குவோம்!*\nமுதல் படியைத் தேர்ந்தெடுக்கவும்:",
    intentHelp: "💡 *எளிய உதவி:*\n• டைப் செய்யாமல் கீழே உள்ள பட்டனைத் தட்டவும்.\n• பேச *CALL* என அனுப்பவும்.\n• மீண்டும் தொடங்க *RESET* என அனுப்பவும்.\n\n👇 *தொடருங்கள்:*",
    errUnrecognized: "⚠️ *\"{input}\" புரியவில்லை.*\n\nகீழே உள்ள விருப்பங்களில் ஒன்றைத் தட்டவும்:",
