    intentPrice: "💰 *ನೇರ ಫ್ಯಾಕ್ಟರಿ ದರ + ಪ್ರೈಸ್ ಮ್ಯಾಚ್:*\n• ಕ್ಯಾಮೆರಾ ಬೆಲೆ ₹1,409 + GST ಯಿಂದ ಶುರು (1-ವರ್ಷದ ಉಚಿತ ವಾರಂಟಿ).\n• DVR/NVR, ಸ್ಟೋರೇಜ್, ವೈರ್ & ಪೂರ್ತಿ ಫಿಟ್ಟಿಂಗ್ ಸೇರಿರುತ್ತದೆ.\n\n_ನಿಖರ ಬೆಲೆ ನೋಡಲು ಕೆಳಗೆ ಉತ್ತರಿಸಿ:_",
