    intentLocation: "🚚 *ಭಾರತದಾದ್ಯಂತ ಡೋರ್‌ಸ್ಟೆಪ್ ಫಿಟ್ಟಿಂಗ್:*\nಮನೆ, ಅಂಗಡಿ & ಆಫೀಸ್‌ಗೆ ಅದೇ/ಮರುದಿನ ಸ್ಟಾಕ್ ಜೊತೆ ಲೋಕಲ್ ಟೆಕ್ನಿಷಿಯನ್ ಬರುತ್ತಾರೆ.\n\n_ನಿಮ್ಮ ಪಿನ್‌ಕೋಡ್ ಮ್ಯಾಚ್ ಮಾಡಲು ಕೆಳಗೆ ಪೂರ್ಣಗೊಳಿಸಿ:_",
    intentReset: "🔄 *ಹೊಸದಾಗಿ ಶುರು ಮಾಡೋಣ!*\nಹಂತ 1 ರಿಂದ CCTV ಸೆಟಪ್ ಆರಿಸೋಣ:",
    intentHelp: "💡 *TEAM CCTV ತ್ವರಿತ ಸಹಾಯ:*\n• ಕೆಳಗಿನ ಯಾವುದೇ ಬಟನ್/ಲಿಸ್ಟ್ ಒತ್ತಿ.\n• ಟೆಕ್ನಿಷಿಯನ್ ಕರೆಗಾಗಿ *CALL* ಟೈಪ್ ಮಾಡಿ.\n• ಹೊಸದಾಗಿ ಶುರು ಮಾಡಲು *RESET* ಟೈಪ್ ಮಾಡಿ.\n\n👇 *ಇಲ್ಲಿ ಮುಂದುವರಿಸಿ:*",
    errUnrecognized: "⚠️ *\"{input}\" ಅರ್ಥವಾಗಲಿಲ್ಲ.*\n\nದಯವಿಟ್ಟು ಕೆಳಗಿನ ಆಯ್ಕೆಗಳಲ್ಲಿ ಒಂದನ್ನು ಒತ್ತಿ:",
